package exercise

import (
	"net/http"
	"net/http/httptest"
	"testing"
)

func run(t *testing.T, target string) *httptest.ResponseRecorder {
	t.Helper()
	rec := httptest.NewRecorder()
	Search(rec, httptest.NewRequest(http.MethodGet, target, nil))
	return rec
}

func TestAcceptedQueries(t *testing.T) {
	cases := []struct{ target, want string }{
		{"/search?q=go&page=3", "q=go page=3"},
		{"/search?q=go", "q=go page=1"},
		{"/search?q=go+lang&page=2", "q=go lang page=2"},
		{"/search?q=caf%C3%A9&page=1", "q=café page=1"},
		{"/search?q=go&page=10&sort=new", "q=go page=10"},
	}
	for _, c := range cases {
		rec := run(t, c.target)
		if rec.Code != http.StatusOK {
			t.Errorf("%s: status = %d, want 200", c.target, rec.Code)
			continue
		}
		if got := rec.Body.String(); got != c.want {
			t.Errorf("%s: body = %q, want %q", c.target, got, c.want)
		}
	}
}

func TestRejectedQueries(t *testing.T) {
	cases := []struct{ target, why string }{
		{"/search?page=2", "q is missing"},
		{"/search?q=&page=1", "q is present but empty"},
		{"/search?q=go&page=", "page is present but empty"},
		{"/search?q=go&page=abc", "page is not a number"},
		{"/search?q=go&page=0", "page is below one"},
		{"/search?q=go&page=-2", "page is negative"},
		{"/search?q=go&page=1&page=2", "page was sent twice"},
		{"/search?q=a&q=b&page=1", "q was sent twice"},
		{"/search?q=go&junk=%zz", "the query string is malformed"},
		{"/search?q=go&a=1;b=2", "the query string is malformed"},
	}
	for _, c := range cases {
		if rec := run(t, c.target); rec.Code != http.StatusBadRequest {
			t.Errorf("%s: status = %d, want 400 (%s)", c.target, rec.Code, c.why)
		}
	}
}

