package exercise

import (
	"fmt"
	"net/http"
	"net/url"
	"strconv"
)

func Search(w http.ResponseWriter, r *http.Request) {
	values, err := url.ParseQuery(r.URL.RawQuery)
	if err != nil {
		http.Error(w, "malformed query", http.StatusBadRequest)
		return
	}
	q := values["q"]
	if len(q) != 1 || q[0] == "" {
		http.Error(w, "q is required exactly once", http.StatusBadRequest)
		return
	}
	page := 1
	if raw, ok := values["page"]; ok {
		if len(raw) != 1 {
			http.Error(w, "page repeated", http.StatusBadRequest)
			return
		}
		n, err := strconv.Atoi(raw[0])
		if err != nil || n < 1 {
			http.Error(w, "bad page", http.StatusBadRequest)
			return
		}
		page = n
	}
	fmt.Fprintf(w, "q=%s page=%d", q[0], page)
}

