package exercise

import (
	"net/http"
	"net/http/httptest"
	"testing"
)

func req(t *testing.T, target, host string) *http.Request {
	t.Helper()
	r := httptest.NewRequest(http.MethodGet, target, nil)
	r.Host = host
	return r
}

func TestOrdinaryRequest(t *testing.T) {
	if got, want := CanonicalURL(req(t, "/files/a/b?x=1", "ex.com")), "http://ex.com/files/a/b?x=1"; got != want {
		t.Errorf("CanonicalURL = %q, want %q", got, want)
	}
}

func TestPathKeepsItsWireForm(t *testing.T) {
	cases := []struct{ target, want string }{
		{"/files/a%2Fb?x=1", "http://ex.com/files/a%2Fb?x=1"},
		{"/x%20y", "http://ex.com/x%20y"},
		{"/caf%C3%A9?q=a%2Fb", "http://ex.com/caf%C3%A9?q=a%2Fb"},
		{"/a%2e%2e/b", "http://ex.com/a%2e%2e/b"},
		{"/", "http://ex.com/"},
	}
	for _, c := range cases {
		if got := CanonicalURL(req(t, c.target, "ex.com")); got != c.want {
			t.Errorf("target %s: CanonicalURL = %q, want %q", c.target, got, c.want)
		}
	}
}

func TestQueryOmittedWhenAbsent(t *testing.T) {
	if got, want := CanonicalURL(req(t, "/items", "ex.com")), "http://ex.com/items"; got != want {
		t.Errorf("CanonicalURL = %q, want %q", got, want)
	}
	if got, want := CanonicalURL(req(t, "/items?", "ex.com")), "http://ex.com/items"; got != want {
		t.Errorf("empty query: CanonicalURL = %q, want %q", got, want)
	}
}

func TestSchemeFollowsTheConnection(t *testing.T) {
	secure := httptest.NewRequest(http.MethodGet, "https://ex.com/a/b?x=1", nil)
	if got, want := CanonicalURL(secure), "https://ex.com/a/b?x=1"; got != want {
		t.Errorf("secure request: CanonicalURL = %q, want %q", got, want)
	}
	plain := req(t, "/a/b", "ex.com")
	if got, want := CanonicalURL(plain), "http://ex.com/a/b"; got != want {
		t.Errorf("plain request: CanonicalURL = %q, want %q", got, want)
	}
}

func TestAuthorityComesFromTheRequestNotTheURL(t *testing.T) {
	r := req(t, "/a", "virtual.example:8443")
	if got, want := CanonicalURL(r), "http://virtual.example:8443/a"; got != want {
		t.Errorf("CanonicalURL = %q, want %q", got, want)
	}
	if r.URL.Host != "" {
		t.Fatal("test precondition: URL.Host should be empty for a server request")
	}
}

