package exercise

import (
	"net/http"
	"net/http/httptest"
	"testing"
	"time"
)

func call(t *testing.T, method, cookieHeader, token string) *http.Response {
	t.Helper()
	r := httptest.NewRequest(method, "/session", nil)
	if cookieHeader != "" {
		r.Header.Set("Cookie", cookieHeader)
	}
	if token != "" {
		r.Header.Set("X-Session-Token", token)
	}
	rec := httptest.NewRecorder()
	Session(rec, r)
	return rec.Result()
}

func setCookie(t *testing.T, res *http.Response, name string) *http.Cookie {
	t.Helper()
	for _, c := range res.Cookies() {
		if c.Name == name {
			return c
		}
	}
	t.Fatalf("no cookie named %q was set; got %v", name, res.Cookies())
	return nil
}

func bodyOf(t *testing.T, res *http.Response) string {
	t.Helper()
	buf := make([]byte, 256)
	n, _ := res.Body.Read(buf)
	return string(buf[:n])
}

func TestNoSessionStartsOneAnonymously(t *testing.T) {
	res := call(t, http.MethodGet, "", "")
	if res.StatusCode != http.StatusOK {
		t.Fatalf("status = %d, want 200", res.StatusCode)
	}
	if got := bodyOf(t, res); got != "new anon" {
		t.Errorf("body = %q, want %q", got, "new anon")
	}
	c := setCookie(t, res, "sid")
	if c.Value != "anon" {
		t.Errorf("cookie value = %q, want %q", c.Value, "anon")
	}
}

func TestNoSessionTakesTheTokenFromTheHeader(t *testing.T) {
	res := call(t, http.MethodGet, "", "t-42")
	if got := bodyOf(t, res); got != "new t-42" {
		t.Errorf("body = %q, want %q", got, "new t-42")
	}
	if c := setCookie(t, res, "sid"); c.Value != "t-42" {
		t.Errorf("cookie value = %q, want %q", c.Value, "t-42")
	}
}

func TestTheNewCookieCarriesItsScopeAndProtections(t *testing.T) {
	c := setCookie(t, call(t, http.MethodGet, "", "t-42"), "sid")
	if c.Path != "/" {
		t.Errorf("Path = %q, want %q", c.Path, "/")
	}
	if c.MaxAge != 3600 {
		t.Errorf("lifetime = %d seconds, want 3600", c.MaxAge)
	}
	if !c.HttpOnly {
		t.Error("the cookie is reachable from page scripts; it should not be")
	}
	if !c.Secure {
		t.Error("the cookie would travel over a plain connection; it should not")
	}
	if c.SameSite != http.SameSiteLaxMode {
		t.Errorf("SameSite = %v, want the lax setting (%v)", c.SameSite, http.SameSiteLaxMode)
	}
}

func TestOneSessionCookieResumes(t *testing.T) {
	res := call(t, http.MethodGet, "sid=abc", "")
	if got := bodyOf(t, res); got != "resume abc" {
		t.Errorf("body = %q, want %q", got, "resume abc")
	}
	if len(res.Cookies()) != 0 {
		t.Errorf("resuming set %d cookies, want none", len(res.Cookies()))
	}
}

func TestOtherCookiesAreIgnored(t *testing.T) {
	res := call(t, http.MethodGet, "theme=dark; sid=abc; lang=pt", "")
	if got := bodyOf(t, res); got != "resume abc" {
		t.Errorf("body = %q, want %q", got, "resume abc")
	}

	res2 := call(t, http.MethodGet, "theme=dark; lang=pt", "")
	if got := bodyOf(t, res2); got != "new anon" {
		t.Errorf("with no sid present, body = %q, want %q", got, "new anon")
	}
}

func TestTwoSessionCookiesAreAmbiguous(t *testing.T) {
	res := call(t, http.MethodGet, "sid=abc; theme=dark; sid=def", "")
	if res.StatusCode != http.StatusConflict {
		t.Fatalf("status = %d, want 409", res.StatusCode)
	}
	if len(res.Cookies()) != 0 {
		t.Errorf("the ambiguous case set %d cookies, want none", len(res.Cookies()))
	}
}

func TestDeleteClearsTheCookie(t *testing.T) {
	for _, header := range []string{"sid=abc", ""} {
		res := call(t, http.MethodDelete, header, "")
		if res.StatusCode != http.StatusOK {
			t.Fatalf("cookie header %q: status = %d, want 200", header, res.StatusCode)
		}
		if got := bodyOf(t, res); got != "bye" {
			t.Errorf("cookie header %q: body = %q, want %q", header, got, "bye")
		}
		c := setCookie(t, res, "sid")
		if c.Value != "" {
			t.Errorf("cleared cookie value = %q, want it empty", c.Value)
		}
		if c.Path != "/" {
			t.Errorf("cleared cookie Path = %q, want %q so it replaces the original", c.Path, "/")
		}
		expired := c.MaxAge < 0 || (!c.Expires.IsZero() && c.Expires.Before(time.Now()))
		if !expired {
			t.Errorf("cleared cookie does not expire immediately: MaxAge=%d Expires=%v", c.MaxAge, c.Expires)
		}
	}
}

solution:
package exercise

import (
	"fmt"
	"net/http"
)

func Session(w http.ResponseWriter, r *http.Request) {
	if r.Method == http.MethodDelete {
		http.SetCookie(w, &http.Cookie{Name: "sid", Value: "", Path: "/", MaxAge: -1})
		fmt.Fprint(w, "bye")
		return
	}
	switch found := r.CookiesNamed("sid"); len(found) {
	case 0:
		token := r.Header.Get("X-Session-Token")
		if token == "" {
			token = "anon"
		}
		http.SetCookie(w, &http.Cookie{
			Name:     "sid",
			Value:    token,
			Path:     "/",
			MaxAge:   3600,
			HttpOnly: true,
			Secure:   true,
			SameSite: http.SameSiteLaxMode,
		})
		fmt.Fprintf(w, "new %s", token)
	case 1:
		fmt.Fprintf(w, "resume %s", found[0].Value)
	default:
		http.Error(w, "ambiguous session", http.StatusConflict)
	}
}
